INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'hotspot', 'Строй повёрнут лицом вправо. Отметьте на схеме оба фланга строя.', '[]', '[]', '', 2, 20010, '{"meta":{"article":"СУ, п. 7","explanation":"Фланг — правая (левая) оконечность строя. У шеренги, обращённой вправо, оконечности — верхний и нижний военнослужащие.","quote":"7. Фланг - правая (левая) оконечность строя.","difficulty":"2"},"material":"Схема: одношереножный строй, вид сверху. Кружки — военнослужащие, уголок на кружке показывает, куда военнослужащий обращён лицом. Стрелка — направление, куда обращён строй.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 320\" width=\"480\" height=\"320\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"320\" fill=\"#f4f1e8\"/><g transform=\"translate(240 45) rotate(90)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(240 91) rotate(90)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(240 137) rotate(90)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(240 183) rotate(90)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(240 229) rotate(90)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(240 275) rotate(90)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><path d=\"M300 160 L350.0 160.0\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/><path d=\"M360 160 L350.0 154.0 L350.0 166.0 Z\" fill=\"#333\"/></svg>","alt":"Одношереножный строй, вид сверху. Военнослужащие обращены лицом вправо (стрелка)."}],"zones":[{"x":45.8,"y":8.1,"w":8.3,"h":11.9,"label":"Верхняя оконечность строя — левый фланг (левая рука военнослужащих)","id":"U1hK0P1A","correct":true},{"x":45.8,"y":80,"w":8.3,"h":11.9,"label":"Нижняя оконечность строя — правый фланг (правая рука военнослужащих)","id":"FC5XMdfA","correct":true},{"x":79.2,"y":12.5,"w":18.8,"h":75,"label":"Сторона, куда военнослужащие обращены лицом (фронт)","id":"eBZYXHP","correct":false},{"x":4.2,"y":12.5,"w":33.3,"h":75,"label":"Сторона, противоположная фронту (тыльная сторона строя)","id":"Jp9OWxO3","correct":false},{"x":47.1,"y":46.9,"w":5.8,"h":6.2,"label":"Промежуток по фронту между соседними военнослужащими (интервал)","id":"r2ozOWaj","correct":false}],"show_labels":false,"partial":false}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-sch-su-01', 'r6-sch-su-line', 'simple', 2, 'su', 'СУ, п. 7', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-sch-su-01');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'hotspot', 'Строй обращён лицом вправо. Укажите правый фланг (правая сторона — по отношению к военнослужащим в строю).', '[]', '[]', '', 3, 20020, '{"meta":{"article":"СУ, п. 7","explanation":"Военнослужащий, обращённый лицом вправо на схеме, имеет правую руку внизу схемы, поэтому правый фланг — нижняя оконечность.","quote":"Фланг - правая (левая) оконечность строя. При поворотах строя названия флангов не изменяются.","difficulty":"3"},"material":"Схема: одношереножный строй, вид сверху. Кружки — военнослужащие, уголок на кружке показывает, куда военнослужащий обращён лицом. Стрелка — направление, куда обращён строй.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 320\" width=\"480\" height=\"320\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"320\" fill=\"#f4f1e8\"/><g transform=\"translate(240 45) rotate(90)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(240 91) rotate(90)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(240 137) rotate(90)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(240 183) rotate(90)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(240 229) rotate(90)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6