INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'hotspot', 'Отметьте на схеме колонну.', '[]', '[]', '', 1, 20040, '{"meta":{"article":"СУ, п. 17","explanation":"Колонна — строй, в котором военнослужащие расположены в затылок друг другу.","quote":"17. Колонна - строй, в котором военнослужащие расположены в затылок друг другу","difficulty":"1"},"material":"Схема: четыре группы военнослужащих, вид сверху. Кружки — военнослужащие, уголок на кружке показывает, куда военнослужащий обращён лицом.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 300\" width=\"480\" height=\"300\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"300\" fill=\"#f4f1e8\"/><g transform=\"translate(50 120) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(50 160) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(90 120) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(90 160) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(130 120) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(130 160) rotate(0)\"><circle cx