INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'hotspot', 'Отметьте разомкнутый строй.', '[]', '[]', '', 1, 20070, '{"meta":{"article":"СУ, п. 16","explanation":"В разомкнутом строю интервал — один шаг (или указанный командиром).","quote":"В сомкнутом строю военнослужащие в шеренгах расположены по фронту один от другого на интервалах, равных ширине ладони между локтями. В разомкнутом строю военнослужащие в шеренгах расположены по фронту один от другого на интервалах в один шаг","difficulty":"1"},"material":"Схема: две шеренги, вид сверху. Подписи под шеренгами — величина интервалов. Кружки — военнослужащие, уголок на кружке показывает, куда военнослужащий обращён лицом.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 260\" width=\"480\" height=\"260\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"260\" fill=\"#f4f1e8\"/><g transform=\"translate(120 70) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(148 70) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(176 70) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(204 70) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(232 70) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b