INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте буквы на схеме с названиями расстояний в строю.', '[]', '[]', '', 2, 20110, '{"meta":{"article":"СУ, пп. 10–13","explanation":"Интервал — по фронту между военнослужащими, дистанция — в глубину, ширина — между флангами, глубина — от первой шеренги до последней.","quote":"10. Интервал - расстояние по фронту между военнослужащими … 11. Дистанция - расстояние в глубину между военнослужащими … 12. Ширина строя - расстояние между флангами. … 13. Глубина строя - расстояние от первой шеренги","difficulty":"2"},"material":"Схема: двухшереножный строй, вид сверху, стрелка — фронт. Буквы А–Г обозначают отрезки. Кружки — военнослужащие, уголок на кружке показывает, куда военнослужащий обращён лицом.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 320\" width=\"480\" height=\"320\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"320\" fill=\"#f4f1e8\"/><g transform=\"translate(120 140) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(120 190) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(170 140) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(170 190) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><