INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'hotspot', 'Двухшереножный строй выполняет поворот «Кру-ГОМ». Военнослужащий неполного ряда отмечен красным кольцом. Где он окажется после поворота?', '[]', '[]', '', 3, 20120, '{"meta":{"article":"СУ, п. 15.1","explanation":"После поворота кругом впереди оказывается бывшая вторая шеренга; военнослужащий неполного ряда переходит во впереди стоящую шеренгу — на пустое место за собой.","quote":"При повороте двухшереножного строя кругом военнослужащий неполного ряда переходит во впереди стоящую шеренгу.","difficulty":"3"},"material":"Схема: двухшереножный строй до поворота, вид сверху, стрелка — фронт. Пунктир — пустое место. Кружки — военнослужащие, уголок на кружке показывает, куда военнослужащий обращён лицом.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 300\" width=\"480\" height=\"300\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"300\" fill=\"#f4f1e8\"/><g transform=\"translate(120 120) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(180 120) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(240 120) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><circle cx=\"240\" cy=\"120\" r=\"19\" fill=\"none\" stroke=\"#b0413e\" stroke-width=\"3\"/><g transform=\"translate(300 120) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\