INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'hotspot', 'Отметьте все направления, в которые военнослужащий может оказаться обращён после выполнения одной команды поворота на месте.', '[]', '[]', '', 2, 20180, '{"meta":{"article":"СУ, п. 23","explanation":"Пять команд: напра-ВО (90° вправо), пол-оборота напра-ВО (45° вправо), нале-ВО (90° влево), пол-оборота нале-ВО (45° влево), кру-ГОМ (180°). Поворотов на 135° одной командой нет.","quote":"23. Повороты на месте выполняются по командам: \"Напра-ВО\", \"Пол-оборота напра-ВО\", \"Нале-ВО\", \"Пол-оборота нале-ВО\", \"Кру-ГОМ\". … Повороты кругом (на 1/2 круга), налево (на 1/4 круга), пол-оборота налево (на 1/8 круга) производятся в сторону левой руки","difficulty":"2"},"material":"Схема: военнослужащий, вид сверху. Уголок на кружке показывает, куда он обращён лицом сейчас. Серые стрелки — возможные направления.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 320\" width=\"480\" height=\"320\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"320\" fill=\"#f4f1e8\"/><path d=\"M240.0 130.0 L240.0 77.0\" stroke=\"#8a8a8a\" stroke-width=\"2\" fill=\"none\"/><path d=\"M240.0 68.0 L234.6 77.0 L245.4 77.0 Z\" fill=\"#8a8a8a\"/><path d=\"M261.2 138.8 L298.7 101.3\" stroke=\"#8a8a8a\" stroke-width=\"2\" fill=\"none\"/><path d=\"M305.1 94.9 L294.9 97.4 L302.6 105.1 Z\" fill=\"#8a8a8a\"/><path d=\"M270.0 160.0 L323.0 160.0\" stroke=\"#8a8a8a\" stroke-width=\"2\" fill=\"none\"/><path d=\"M332.0 160.0 L323.0 154.6 L323.0 165.4 Z\" fill=\"#8a8a8a\"/><path d=\"M261.2 181.2 L298.7 218.7\" stroke=\"#8a8a8a\" stroke-width=\"2\" fill=\"none\"/><path d=\"M305.1 225.1 L302.6 214.9 L294.9 222.6 Z\" fill=\"#8a8a8a\"/><path d=\"M240.0 190.0 L240.0 243.0\" stroke=\"#8a8a8a\" stroke-width=\"2\" fill=\"none\"/><path d=\"M240.0 252.0 L245.4 243.0 L234.6 243.0 Z\" fill=\"#8a8a8a\"/><path d=\"M218.8 181.2 L181.3 218.7\" stroke=\"#8a8a8a\" stroke-width=\"2\" fill=\"none\"/><path d=\"M174.9 225.1 L185.1 222.6 L177.4 214.9 Z\" fill=\"#8a8a8a\"/><path d=\"M210.0 160.0 L157.0 160.0\" stroke=\"#8a8a8a\" stroke-width=\"2\" fill=\"none\"/><path d=\"M148.0 160.0 L157.0 165.4 L157.0 154.6 Z\" fill=\"#8a8a8a\"/><path d=\"M218.8 138.8 L181.3 101.3\" stroke=\"#8a8a8a\" stroke-width=\"2\" fill=\"none\"/><path d=\"M174.9 94.9 L177.4 105.1 L185.1 97.4 Z\" fill=\"#8a8a8a\"/><g transform=\"translate(240 160) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"16\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -11 L0 -19 L6 -11\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g></svg>","alt":"Военнослужащий, вид сверху, и восемь стрелок-направлений вокруг него."}],"zones":[{"x":45.4,"y":6.2,"w":9.2,"h":13.8,"label":"Направление вверх","id":"4th789F","correct":false},{"x":62.7,"y":17.2,"w":9.2,"h":13.8,"label":"Направление вверх-вправо","id":"f33LjDsB","correct":true},{"x":70,"y":43.1,"w":9.2,"h":13.8,"label":"Направление вправо","id":"hR59CS05","correct":true},{"x":62.7,"y":69.1,"w":9.2,"h":13.8,"label":"Направление вниз-вправо","id":"gM9aHh94","correct":false},{"x":45.4,"y":80,"w":9.2,"h":13.8,"label":"Направление вниз","id":"wYiU6sjz","correct":true},{"x":28.1,"y":69.1,"w":9.2,"h":13.8,"label":"Направление вниз-влево","id":"bprrPXlt","correct":false},{"x":20.8,"y":43.1,"w":9.2,"h":13.8,"label":"Направление влево","id":"3vezEIOS","correct":true},{"x":28.1,"y":17.2,"w":9.2,"h":13.8,"label":"Направление вверх-влево","id":"O5AMlt1","correct":true}],"show_labels":false,"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-sch-su-18', 'r6-sch-su-turn', 'medium', 2, 'su', 'СУ, п. 23', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-sch-su-18');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Военнослужащий стоит лицом к верхнему краю схемы. Как он будет стоять после команды «Пол-оборота нале-ВО»? (вид сверху)', '[{"id":"kn3w3ze","text":"Вариант А","media":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 120 120\" width=\"120\" height=\"120\"><rect x=\"0\" y=\"0\" width=\"120\" height=\"120\" fill=\"#f4f1e8\"/><circle cx=\"60\" cy=\"60\" r=\"50\" fill=\"none\" stroke=\"#ccc\" stroke-width=\"1\"/><g transform=\"translate(60 60) rotate(45)\"><circle cx=\"0\" cy=\"0\" r=\"18\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -13 L0 -21 L6 -13\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><path d=\"M75.55634918610404 44.44365081389596 L86.1 33.9\" stroke=\"#b0413e\" stroke-width=\"3\" fill=\"none\"/><path d=\"M92.5 27.5 L82.3 30.0 L90.0 37.7 Z\" fill=\"#b0413e\"/></svg>","alt":"Военнослужащий, вид сверху"}},{"id":"BihrmybN","text":"Вариант Б","media":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 120 120\" width=\"120\" height=\"120\"><rect x=\"0\" y=\"0\" width=\"120\" height=\"120\" fill=\"#f4f1e8\"/><circle cx=\"60\" cy=\"60\" r=\"50\" fill=\"none\" stroke=\"#ccc\" stroke-width=\"1\"/><g transform=\"translate(60 60) rotate(315)\"><circle cx=\"0\" cy=\"0\" r=\"18\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -13 L0 -21 L6 -13\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><path d=\"M44.44365081389595 44.44365081389596 L33.9 33.9\" stroke=\"#b0413e\" stroke-width=\"3\" fill=\"none\"/><path d=\"M27.5 27.5 L30.0 37.7 L37.7 30.0 Z\" fill=\"#b0413e\"/></svg>","alt":"Военнослужащий, вид сверху"}},{"id":"00olNG","text":"Вариант В","media":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 120 120\" width=\"120\" height=\"120\"><rect x=\"0\" y=\"0\" width=\"120\" height=\"120\" fill=\"#f4f1e8\"/><circle cx=\"60\" cy=\"60\" r=\"50\" fill=\"none\" stroke=\"#ccc\" stroke-width=\"1\"/><g transform=\"translate(60 60) rotate(270)\"><circle cx=\"0\" cy=\"0\" r=\"18\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -13 L0 -21 L6 -13\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><path d=\"M38.0 60.00000000000001 L23.0 60.0\" stroke=\"#b0413e\" stroke-width=\"3\" fill=\"none\"/><path d=\"M14.0 60.0 L23.0 65.4 L23.0 54.6 Z\" fill=\"#b0413e\"/></svg>","alt":"Военнослужащий, вид сверху"}},{"id":"pDXfXhtG","text":"Вариант Г","media":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 120 120\" width=\"120\" height=\"120\"><rect x=\"0\" y=\"0\" width=\"120\" height=\"120\" fill=\"#f4f1e8\"/><circle cx=\"60\" cy=\"60\" r=\"50\" fill=\"none\" stroke=\"#ccc\" stroke-width=\"1\"/><g transform=\"translate(60 60) rotate(135)\"><circle cx=\"0\" cy=\"0\" r=\"18\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -13 L0 -21 L6 -13\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><path d=\"M75.55634918610404 75.55634918610404 L86.1 86.1\" stroke=\"#b0413e\" stroke-width=\"3\" fill=\"none\"/><path d=\"M92.5 92.5 L90.0 82.3 L82.3 90.0 Z\" fill=\"#b0413e\"/></svg>","alt":"Военнослужащий, вид сверху"}}]', '["BihrmybN"]', '', 2, 20190, '{"meta":{"article":"СУ, п. 23","explanation":"Пол-оборота налево — на 1/8 круга (45°) в сторону левой руки: лицом вверх-влево.","quote":"23. Повороты на месте выполняются по командам: \"Напра-ВО\", \"Пол-оборота напра-ВО\", \"Нале-ВО\", \"Пол-оборота нале-ВО\", \"Кру-ГОМ\". … Повороты кругом (на 1/2 круга), налево (на 1/4 круга), пол-оборота налево (на 1/8 круга) производятся в сторону левой руки","difficulty":"2"},"material":"Варианты — вид сверху, верх схемы — направление, куда военнослужащий был обращён до команды. Кружки — военнослужащие, уголок на кружке показывает, куда военнослужащий обращён лицом."}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-sch-su-19', 'r6-sch-su-turn2', 'simple', 2, 'su', 'СУ, п. 23', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-sch-su-19');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'hotspot', 'Военнослужащий подходит к начальнику вне строя. Отметьте все деления, на которых ему положено остановиться.', '[]', '[]', '', 2, 20200, '{"meta":{"article":"СУ, п. 29","explanation":"При подходе к начальнику вне строя военнослужащий останавливается за два-три шага до него.","quote":"29. При подходе к начальнику вне строя военнослужащий за пять-шесть шагов до него переходит на строевой шаг, за два-три шага останавливается","difficulty":"2"},"material":"Схема: военнослужащий приближается к начальнику, вид сверху. Чёрные деления на линии — шаги, отсчитываемые от начальника (первое деление — один шаг до него). Отмечаются области под делениями.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 190\" width=\"480\" height=\"190\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"190\" fill=\"#f4f1e8\"/><g transform=\"translate(40 110)\"><circle r=\"15\" fill=\"#8a5a3c\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -10 L0 -18 L6 -10\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\" transform=\"rotate(90)\"/></g><text x=\"40\" y=\"80\" font-family=\"Arial, sans-serif\" font-size=\"13\" text-anchor=\"middle\" fill=\"#222\">начальник</text><g transform=\"translate(452 110) rotate(270)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><text x=\"452\" y=\"80\" font-family=\"Arial, sans-serif\" font-size=\"12\" text-anchor=\"end\" fill=\"#222\">военнослужащий</text><path d=\"M55 110 L432 110\" stroke=\"#888\" stroke-width=\"2\" fill=\"none\" stroke-dasharray=\"6 4\"/><path d=\"M86 100 L86 120\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/><path d=\"M132 100 L132 120\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/><path d=\"M178 100 L178 120\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/><path d=\"M224 100 L224 120\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/><path d=\"M270 100 L270 120\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/><path d=\"M316 100 L316 120\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/><path d=\"M362 100 L362 120\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/><path d=\"M408 100 L408 120\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/></svg>","alt":"Линия с делениями-шагами между военнослужащим и начальником."}],"zones":[{"x":14.2,"y":66.3,"w":7.5,"h":21.1,"label":"1 шаг(а) до начальника","id":"XZB7doM","correct":false},{"x":23.8,"y":66.3,"w":7.5,"h":21.1,"label":"2 шаг(а) до начальника","id":"rMhaiT1","correct":true},{"x":33.3,"y":66.3,"w":7.5,"h":21.1,"label":"3 шаг(а) до начальника","id":"NFLgxE8","correct":true},{"x":42.9,"y":66.3,"w":7.5,"h":21.1,"label":"4 шаг(а) до начальника","id":"z6vT802K","correct":false},{"x":52.5,"y":66.3,"w":7.5,"h":21.1,"label":"5 шаг(а) до начальника","id":"HbMhUNBb","correct":false},{"x":62.1,"y":66.3,"w":7.5,"h":21.1,"label":"6 шаг(а) до начальника","id":"JnbRBFq","correct":false},{"x":71.7,"y":66.3,"w":7.5,"h":21.1,"label":"7 шаг(а) до начальника","id":"KRytgr7","correct":false},{"x":81.2,"y":66.3,"w":7.5,"h":21.1,"label":"8 шаг(а) до начальника","id":"kN2wPxwa","correct":false}],"show_labels":false,"partial":false}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-sch-su-20', 'r6-sch-su-steps', 'simple', 2, 'su', 'СУ, п. 29', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-sch-su-20');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'hotspot', 'На каких делениях военнослужащий, подходящий к начальнику вне строя, переходит на строевой шаг? Отметьте все подходящие.', '[]', '[]', '', 2, 20210, '{"meta":{"article":"СУ, п. 29","explanation":"За пять-шесть шагов до начальника — переход на строевой шаг, за два-три — остановка.","quote":"29. При подходе к начальнику вне строя военнослужащий за пять-шесть шагов до него переходит на строевой шаг","difficulty":"2"},"material":"Схема: военнослужащий приближается к начальнику, вид сверху. Чёрные деления на линии — шаги, отсчитываемые от начальника (первое деление — один шаг до него). Отмечаются области под делениями.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 190\" width=\"480\" height=\"190\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"190\" fill=\"#f4f1e8\"/><g transform=\"translate(40 110)\"><circle r=\"15\" fill=\"#8a5a3c\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -10 L0 -18 L6 -10\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\" transform=\"rotate(90)\"/></g><text x=\"40\" y=\"80\" font-family=\"Arial, sans-serif\" font-size=\"13\" text-anchor=\"middle\" fill=\"#222\">начальник</text><g transform=\"translate(452 110) rotate(270)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><text x=\"452\" y=\"80\" font-family=\"Arial, sans-serif\" font-size=\"12\" text-anchor=\"end\" fill=\"#222\">военнослужащий</text><path d=\"M55 110 L432 110\" stroke=\"#888\" stroke-width=\"2\" fill=\"none\" stroke-dasharray=\"6 4\"/><path d=\"M86 100 L86 120\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/><path d=\"M132 100 L132 120\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/><path d=\"M178 100 L178 120\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/><path d=\"M224 100 L224 120\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/><path d=\"M270 100 L270 120\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/><path d=\"M316 100 L316 120\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/><path d=\"M362 100 L362 120\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/><path d=\"M408 100 L408 120\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/></svg>","alt":"Линия с делениями-шагами между военнослужащим и начальником."}],"zones":[{"x":14.2,"y":66.3,"w":7.5,"h":21.1,"label":"1 шаг(а) до начальника","id":"T8FbBObk","correct":false},{"x":23.8,"y":66.3,"w":7.5,"h":21.1,"label":"2 шаг(а) до начальника","id":"G7txiWBO","correct":false},{"x":33.3,"y":66.3,"w":7.5,"h":21.1,"label":"3 шаг(а) до начальника","id":"p6mo3Ayl","correct":false},{"x":42.9,"y":66.3,"w":7.5,"h":21.1,"label":"4 шаг(а) до начальника","id":"BIVAK64U","correct":false},{"x":52.5,"y":66.3,"w":7.5,"h":21.1,"label":"5 шаг(а) до начальника","id":"OWECG8kU","correct":true},{"x":62.1,"y":66.3,"w":7.5,"h":21.1,"label":"6 шаг(а) до начальника","id":"nS6SXMpP","correct":true},{"x":71.7,"y":66.3,"w":7.5,"h":21.1,"label":"7 шаг(а) до начальника","id":"JrnBSREM","correct":false},{"x":81.2,"y":66.3,"w":7.5,"h":21.1,"label":"8 шаг(а) до начальника","id":"rbbr3e31","correct":false}],"show_labels":false,"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-sch-su-21', 'r6-sch-su-steps', 'medium', 2, 'su', 'СУ, п. 29', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-sch-su-21');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'hotspot', 'Военнослужащий без головного убора стоит на месте вне строя, к нему приближается начальник. Отметьте деления, на которых нужно повернуться в сторону начальника и принять строевую стойку.', '[]', '[]', '', 2, 20220, '{"meta":{"article":"СУ, п. 25","explanation":"Воинское приветствие на месте вне строя — за три-четыре шага до начальника.","quote":"25. Для выполнения воинского приветствия на месте вне строя без головного убора за три-четыре шага до начальника (старшего) повернуться в его сторону, принять строевую стойку и смотреть ему в лицо","difficulty":"2"},"material":"Схема: расстояние между военнослужащим и начальником, вид сверху. Чёрные деления на линии — шаги, отсчитываемые от начальника (первое деление — один шаг до него). Отмечаются области под делениями.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 190\" width=\"480\" height=\"190\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"190\" fill=\"#f4f1e8\"/><g transform=\"translate(40 110)\"><circle r=\"15\" fill=\"#8a5a3c\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -10 L0 -18 L6 -10\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\" transform=\"rotate(90)\"/></g><text x=\"40\" y=\"80\" font-family=\"Arial, sans-serif\" font-size=\"13\" text-anchor=\"middle\" fill=\"#222\">начальник</text><g transform=\"translate(452 110) rotate(270)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><text x=\"452\" y=\"80\" font-family=\"Arial, sans-serif\" font-size=\"12\" text-anchor=\"end\" fill=\"#222\">военнослужащий</text><path d=\"M55 110 L432 110\" stroke=\"#888\" stroke-width=\"2\" fill=\"none\" stroke-dasharray=\"6 4\"/><path d=\"M86 100 L86 120\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/><path d=\"M132 100 L132 120\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/><path d=\"M178 100 L178 120\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/><path d=\"M224 100 L224 120\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/><path d=\"M270 100 L270 120\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/><path d=\"M316 100 L316 120\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/><path d=\"M362 100 L362 120\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/><path d=\"M408 100 L408 120\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/></svg>","alt":"Линия с делениями-шагами между военнослужащим и начальником."}],"zones":[{"x":14.2,"y":66.3,"w":7.5,"h":21.1,"label":"1 шаг(а) до начальника","id":"OcR7Dzn","correct":false},{"x":23.8,"y":66.3,"w":7.5,"h":21.1,"label":"2 шаг(а) до начальника","id":"V9GkezqF","correct":false},{"x":33.3,"y":66.3,"w":7.5,"h":21.1,"label":"3 шаг(а) до начальника","id":"OHjj4s71","correct":true},{"x":42.9,"y":66.3,"w":7.5,"h":21.1,"label":"4 шаг(а) до начальника","id":"WWJXF2z7","correct":true},{"x":52.5,"y":66.3,"w":7.5,"h":21.1,"label":"5 шаг(а) до начальника","id":"PuGSZNC","correct":false},{"x":62.1,"y":66.3,"w":7.5,"h":21.1,"label":"6 шаг(а) до начальника","id":"0EPFzsRv","correct":false},{"x":71.7,"y":66.3,"w":7.5,"h":21.1,"label":"7 шаг(а) до начальника","id":"F1oyJgEP","correct":false},{"x":81.2,"y":66.3,"w":7.5,"h":21.1,"label":"8 шаг(а) до начальника","id":"OZaf1R2x","correct":false}],"show_labels":false,"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-sch-su-22', 'r6-sch-su-steps', 'full', 2, 'su', 'СУ, п. 25', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-sch-su-22');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'hotspot', 'Подана команда «Рядовой Иванов. ВЫЙТИ ИЗ СТРОЯ НА ТРИ ШАГА». Иванов (отмечен красным кольцом) стоит во второй шеренге. Где он должен остановиться?', '[]', '[]', '', 3, 20230, '{"meta":{"article":"СУ, п. 27","explanation":"Шаги при выходе из строя считаются от первой шеренги, даже если военнослужащий стоит во второй.","quote":"По первой команде военнослужащий строевым шагом выходит из строя на указанное количество шагов, считая от первой шеренги, останавливается и поворачивается лицом к строю.","difficulty":"3"},"material":"Схема: двухшереножный строй, вид сверху, строй обращён вверх. Деления на пунктире — шаги от первой шеренги. Отмечаются области справа от делений. Кружки — военнослужащие, уголок на кружке показывает, куда военнослужащий обращён лицом.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 340\" width=\"480\" height=\"340\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"340\" fill=\"#f4f1e8\"/><g transform=\"translate(160 255) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(160 300) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(200 255) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(200 300) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(240 255) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(240 300) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><circle cx=\"240\" cy=\"300\" r=\"19\" fill=\"none\" stroke=\"#b0413e\" stroke-width=\"3\"/><g transform=\"translate(280 255) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(280 300) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(320 255) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(320 300) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><path d=\"M240 238 L240 30\" stroke=\"#999\" stroke-width=\"2\" fill=\"none\" stroke-dasharray=\"5 4\"/><path d=\"M228 219 L252 219\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/><path d=\"M228 183 L252 183\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/><path d=\"M228 147 L252 147\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/><path d=\"M228 111 L252 111\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/><path d=\"M228 75 L252 75\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/><path d=\"M228 39 L252 39\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/></svg>","alt":"Двухшереножный строй и пунктир с делениями впереди строя."}],"zones":[{"x":53.8,"y":7.4,"w":9.2,"h":8.2,"label":"6 шаг(а) от первой шеренги","id":"7LdPjFJn","correct":false},{"x":53.8,"y":17.9,"w":9.2,"h":8.2,"label":"5 шаг(а) от первой шеренги","id":"jtOJpzOv","correct":false},{"x":53.8,"y":28.5,"w":9.2,"h":8.2,"label":"4 шаг(а) от первой шеренги","id":"JtX3SJKR","correct":false},{"x":53.8,"y":39.1,"w":9.2,"h":8.2,"label":"3 шаг(а) от первой шеренги","id":"nzElHvn","correct":true},{"x":53.8,"y":49.7,"w":9.2,"h":8.2,"label":"2 шаг(а) от первой шеренги (3 шага, если считать от второй шеренги)","id":"M1THSy5j","correct":false},{"x":53.8,"y":60.3,"w":9.2,"h":8.2,"label":"1 шаг(а) от первой шеренги","id":"RG9GNWVN","correct":false}],"show_labels":false,"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-sch-su-23', 'r6-sch-su-exit', 'full', 3, 'su', 'СУ, п. 27', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-sch-su-23');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'hotspot', 'Объявлено общее построение. Отметьте, где должен находиться военнослужащий ГУ ВП.', '[]', '[]', '', 1, 20240, '{"meta":{"article":"СУ, гл. II, п. 21","explanation":"Военнослужащий ГУ ВП при общем построении находится перед строем и контролирует явку и соблюдение уставов.","quote":"21. При объявлении общего построения военнослужащий ГУ ВП обязан находится перед строем и контролировать явку и соблюдение Уставов военнослужащими.","difficulty":"1"},"material":"Схема: двухшереножный строй, вид сверху; стрелка справа показывает, куда обращён строй. Кружки — военнослужащие, уголок на кружке показывает, куда военнослужащий обращён лицом.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 320\" width=\"480\" height=\"320\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"320\" fill=\"#f4f1e8\"/><g transform=\"translate(130 170) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(130 215) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(175 170) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(175 215) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"13\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -8 L0 -16 L6 -8\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(220 170) rotate(0)\"><circle cx=\"0\" cy=\"0\