INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'hotspot', 'Объявлен код-3. Отметьте вышки, которые по Внутреннему уставу занимают военнослужащие РОиО.', '[]', '[]', '', 3, 20290, '{"meta":{"article":"ВУ, п. 10.16 «а»","explanation":"РОиО прибывают на место объявления кода и занимают близлежащие вышки или защищённые точки в отдалении для силовой поддержки.","quote":"а) прибывают на место объявления кода и производят занятие близлежащих вышек или защищенных точек в отдалении для проведения силовой поддержки.","difficulty":"3"},"material":"Условная схема части, вид сверху: «В» — вышки, красные кружки — места, откуда по рации сообщили о проникновении (цифры — порядок сообщений).","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 330\" width=\"480\" height=\"330\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"330\" fill=\"#e6e1d0\"/><rect x=\"30\" y=\"20\" width=\"420\" height=\"270\" rx=\"0\" fill=\"none\" stroke=\"#555\" stroke-width=\"4\"/><rect x=\"18\" y=\"8\" width=\"24\" height=\"24\" rx=\"0\" fill=\"#8a7a5a\" stroke=\"#222\" stroke-width=\"2\"/><text x=\"30\" y=\"25\" font-family=\"Arial, sans-serif\" font-size=\"12\" text-anchor=\"middle\" fill=\"#fff\" font-weight=\"bold\">В</text><rect x=\"228\" y=\"8\" width=\"24\" height=\"24\" rx=\"0\" fill=\"#8a7a5a\" stroke=\"#222\" stroke-width=\"2\"/><text x=\"240\" y=\"25\" font-family=\"Arial, sans-serif\" font-size=\"12\" text-anchor=\"middle\" fill=\"#fff\" font-weight=\"bold\">В</text><rect x=\"438\" y=\"8\" width=\"24\" height=\"24\" rx=\"0\" fill=\"#8a7a5a\" stroke=\"#222\" stroke-width=\"2\"/><text x=\"450\" y=\"25\" font-family=\"Arial, sans-serif\" font-size=\"12\" text-anchor=\"middle\" fill=\"#fff\" font-weight=\"bold\">В</text><rect x=\"18\" y=\"278\" width=\"24\" height=\"24\" rx=\"0\" fill=\"#8a7a5a\" stroke=\"#