INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'hotspot', 'Мирное время. На схеме показано, сколько постовых стоит на каждом посту части. Отметьте посты, где постовых больше, чем допускает устав.', '[]', '[]', '', 3, 20300, '{"meta":{"article":"КПС, п. 22","explanation":"В мирное время: КПП №1 — не более 4, КПП №2 — не более 6, вышка — не более 4, главный склад — не более 3, полигон — не более 5, комендатура — не более 2.","quote":"• контрольно-пропускной пункт №1 (главный КПП), не более 4 постовых в мирное время, не более 6 постовых в время чрезвычайной ситуации и иных; … • контрольно-пропускной пункт №2 (запасной КПП), не более 6 постовых в мирное время, не более 8 постовых в время чрезвычайной ситуации и иных; … • вышки №1 - №9 по периметру воинской части, не более 4 постовых; … • главный склад, не более 3 постовых; … • военный полигон, не более 5 постовых; … • военная комендатура, не более 2 постовых;","difficulty":"3"},"material":"Схема постов караула части. Кружки в карточке — постовые на этом посту.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 300\" width=\"480\" height=\"300\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"300\" fill=\"#f4f1e8\"/><rect x=\"10\" y=\"10\" width=\"147\" height=\"135\" rx=\"6\" fill=\"#ebe5d3\" stroke=\"#555\" stroke-width=\"2\"/><text x=\"83\" y=\"36\" font-family=\"Arial, sans-serif\" font-size=\"13\" text-anchor=\"middle\" fill=\"#222\" font-weight=\"bold\">КПП №1</text><g transform=\"translate(32 72) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"10\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -5 L0 -13 L6 -5\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><g transform=\"translate(58 72) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"10\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 