INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'hotspot', 'КПП №1 работает в обычном режиме. Отметьте транспорт, для проезда которого всё равно может использоваться КПП №2.', '[]', '[]', '', 2, 20320, '{"meta":{"article":"КПС, пп. 31, 31.1","explanation":"КПП №2 используется только при невозможности использовать КПП №1, но может использоваться для колонн снабжения, призывных колонн, патрулей ВП, командного состава бригады и правительственных кортежей.","quote":"31. Контрольно-пропускной пункт №2 используется исключительно при невозможности использования контрольно-пропускного пункта №1. … 31.1 Контрольно-пропускной пункт №2 может использовать для проезда колонн снабжения, призывных колонн, патрулей военной полиции, командного состава бригады, правительственных кортежей.","difficulty":"2"},"material":"Схема: забор части с двумя КПП, ниже — подъезжающий транспорт с подписями.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 300\" width=\"480\" height=\"300\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"300\" fill=\"#f4f1e8\"/><path d=\"M0 70 L480 70\" stroke=\"#555\" stroke-width=\"5\" fill=\"none\"/><rect x=\"60\" y=\"55\" width=\"90\" height=\"30\" rx=\"0\" fill=\"#bbb\" stroke=\"#222\" stroke-width=\"2\"/><text x=\"105\" y=\"75\" font-family=\"Arial, sans-serif\" font-size=\"13\" text-anchor=\"middle\" fill=\"#222\" font-weight=\"bold\">КПП №1</text><rect x=\"330\" y=\"55\" width=\"90\" height=\"30\" rx=\"0\" fill=\"#bbb\" stroke=\"#222\" stroke-width=\"2\"/><text x=\"375\" y=\"75\" font-family=\"Arial, sans-serif\" font-size=\"13\" text-anchor=\"middle\" fill=\"#222\" font-weight=\"bold\">КПП №2</text><text x=\"240\" y=\"40\" font-family=\"Arial, sans-serif\" font-size=\"13\" text-anchor=\"middle\" fill=\"#555\">территория части</text><g transform=\"translate(52 165) 