INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'hotspot', 'Все автомобили на схеме стоят (не движутся). Отметьте те, чья остановка нарушает правила остановки у пешеходного перехода и на тротуаре.', '[]', '[]', '', 3, 20340, '{"meta":{"article":"КоАП, ст. 9.30","explanation":"Запрещены остановка и стоянка на пешеходном переходе и ближе 5 метров перед ним, а также на тротуаре. За 10 м до перехода и после перехода эта норма остановку не запрещает.","quote":"Остановка или стоянка транспортных средств на пешеходном переходе и ближе 5 метров перед ним, остановка или стоянка транспортных средств на тротуаре","difficulty":"3"},"material":"Схема дороги, вид сверху. Прямоугольники — автомобили, тёмная полоса — лобовое стекло (перед машины). Движение правостороннее. Белые полосы поперёк дороги — пешеходный переход, светлые полосы по краям — тротуары. Размеры — расстояние от автомобиля до перехода.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\" width=\"480\" height=\"270\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"270\" fill=\"#f4f1e8\"/><rect x=\"0\" y=\"40\" width=\"480\" height=\"30\" rx=\"0\" fill=\"#d9d2bf\" stroke=\"none\" stroke-width=\"0\"/><rect x=\"0\" y=\"190\" width=\"480\" height=\"30\" rx=\"0\" fill=\"#d9d2bf\" stroke=\"none\" stroke-width=\"0\"/><rect x=\"0\" y=\"70\" width=\"480\" height=\"120\" rx=\"0\" fill=\"#9a9a92\" stroke=\"none\" stroke-width=\"0\"/><path d=\"M0 130 L480 130\" stroke=\"#fff\" stroke-width=\"3\" fill=\"none\" stroke-dasharray=\"18 12\"/><path d=\"M0 70 L480 70\" stroke=\"#777\" stroke-width=\"2\" fill=\"none\"/><path d=\"M0 190 L480 190\" stroke=\"#777\" stroke-width=\"2\" fill=\"none\"/><rect x=\"300\" y=\"74\" width=\"40\" height=\"8\" rx=\"0\" fill=\"#fff\" stroke=\"none\" stroke-width=\"0\"/><rect x=\"300\" y=\"88\" width=\"40\"