INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'hotspot', 'Автомобили стоят у остановки маршрутного транспорта (вынужденных остановок нет). Отметьте автомобили, остановка которых запрещена.', '[]', '[]', '', 3, 20350, '{"meta":{"article":"КоАП, ст. 9.31","explanation":"Запрещена остановка на месте остановки маршрутного транспорта и ближе 15 м от него, кроме посадки/высадки пассажиров и вынужденной остановки. 20 м — дальше 15 м.","quote":"Остановка или стоянка транспортных средств в местах остановки маршрутных транспортных средств либо ближе 15 метров от мест остановки маршрутных транспортных средств, за исключением остановки для посадки или высадки пассажиров, вынужденной остановки","difficulty":"3"},"material":"Схема дороги, вид сверху. Прямоугольники — автомобили, тёмная полоса — лобовое стекло (перед машины). Движение правостороннее. Жёлтый пунктир — место остановки маршрутного транспорта, красный кружок — пассажир, выходящий из машины. Размеры — от автомобиля до места остановки.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 280\" width=\"480\" height=\"280\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"280\" fill=\"#f4f1e8\"/><rect x=\"0\" y=\"40\" width=\"480\" height=\"30\" rx=\"0\" fill=\"#d9d2bf\" stroke=\"none\" stroke-width=\"0\"/><rect x=\"0\" y=\"190\" width=\"480\" height=\"30\" rx=\"0\" fill=\"#d9d2bf\" stroke=\"none\" stroke-width=\"0\"/><rect x=\"0\" y=\"70\" width=\"480\" height=\"120\" rx=\"0\" fill=\"#9a9a92\" stroke=\"none\" stroke-width=\"0\"/><path d=\"M0 130 L480 130\" stroke=\"#fff\" stroke-width=\"3\" fill=\"none\" stroke-dasharray=\"18 12\"/><path d=\"M0 70 L480 70\" stroke=\"#777\" stroke-width=\"2\" fill=\"none\"/><path d=\"M0 190 L480 190\" stroke=\"#777\" stroke-width=\"2\" fill=\"none\"/><rect x=\"240\" y=\"136\" width=\"100\" height=\"