INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'hotspot', 'Вне населённого пункта: чей водитель занимает левую полосу, когда правая свободна?', '[]', '[]', '', 2, 20400, '{"meta":{"article":"КоАП, ст. 9.23","explanation":"Вне населённых пунктов запрещено двигаться по левым полосам при свободных правых.","quote":"Движение вне населенных пунктов по левым полосам движения при свободных правых","difficulty":"2"},"material":"Схема дороги вне населённого пункта, вид сверху: по две полосы в каждом направлении, двойная сплошная посередине, по краям — обочины. Прямоугольники — автомобили, тёмная полоса — лобовое стекло (перед машины). Движение правостороннее. Синяя стрелка — автомобиль движется в эту сторону; автомобиль без стрелки стоит.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 320\" width=\"480\" height=\"320\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"320\" fill=\"#f4f1e8\"/><rect x=\"70\" y=\"0\" width=\"340\" height=\"320\" rx=\"0\" fill=\"#9a9a92\" stroke=\"none\" stroke-width=\"0\"/><rect x=\"70\" y=\"0\" width=\"30\" height=\"320\" rx=\"0\" fill=\"#b8b19c\" stroke=\"none\" stroke-width=\"0\"/><rect x=\"380\" y=\"0\" width=\"30\" height=\"320\" rx=\"0\" fill=\"#b8b19c\" stroke=\"none\" stroke-width=\"0\"/><path d=\"M100 0 L100 320\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/><path d=\"M380 0 L380 320\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/><path d=\"M236 0 L236 320\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/><path d=\"M244 0 L244 320\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/><path d=\"M170 0 L170 320\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\" stroke-dasharray=\"14 12\"/><path d=\"M310 0 L310 320\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\" stroke-dasharray=\"14 12\"/><g transform=\"translate(277 130) rotate(0)\