INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'hotspot', 'По дороге движется организованная транспортная колонна военных грузовиков. Найдите водителя, нарушающего правила проезда относительно колонны.', '[]', '[]', '', 2, 20410, '{"meta":{"article":"КоАП, ст. 9.25","explanation":"Запрещено пересекать организованную транспортную колонну или занимать место в ней.","quote":"пересечение организованной транспортной или пешей колонны либо занятие места в ней","difficulty":"2"},"material":"Схема дороги, вид сверху. Зелёные машины с тёмной кабиной — грузовики колонны (движутся вправо). Прямоугольники — автомобили, тёмная полоса — лобовое стекло (перед машины). Движение правостороннее. Синяя стрелка — автомобиль движется в эту сторону; автомобиль без стрелки стоит.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 280\" width=\"480\" height=\"280\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"280\" fill=\"#f4f1e8\"/><rect x=\"0\" y=\"40\" width=\"480\" height=\"30\" rx=\"0\" fill=\"#d9d2bf\" stroke=\"none\" stroke-width=\"0\"/><rect x=\"0\" y=\"190\" width=\"480\" height=\"30\" rx=\"0\" fill=\"#d9d2bf\" stroke=\"none\" stroke-width=\"0\"/><rect x=\"0\" y=\"70\" width=\"480\" height=\"120\" rx=\"0\" fill=\"#9a9a92\" stroke=\"none\" stroke-width=\"0\"/><path d=\"M0 130 L480 130\" stroke=\"#fff\" stroke-width=\"3\" fill=\"none\" stroke-dasharray=\"18 12\"/><path d=\"M0 70 L480 70\" stroke=\"#777\" stroke-width=\"2\" fill=\"none\"/><path d=\"M0 190 L480 190\" stroke=\"#777\" stroke-width=\"2\" fill=\"none\"/><rect x=\"200\" y=\"190\" width=\"50\" height=\"90\" rx=\"0\" fill=\"#9a9a92\" stroke=\"none\" stroke-width=\"0\"/><rect x=\"200\" y=\"190\" width=\"50\" height=\"30\" rx=\"0\" fill=\"#9a9a92\" stroke=\"none\" stroke-width=\"0\"/><g transform=\"translate(50 160) rotate(90)\"><re