INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'hotspot', 'Белый автомобиль со спецокраской едет с включёнными синим и красным маячками и сиреной. Отметьте нарушителя.', '[]', '[]', '', 2, 20420, '{"meta":{"article":"КоАП, ст. 9.27","explanation":"Обгон транспортного средства с включёнными маячками и специальным звуковым сигналом — правонарушение.","quote":"Обгон транспортного средства, имеющего нанесенные на наружные поверхности специальные цветографические схемы с включенными проблесковым маячком синего и(или) красного цветов и специальным звуковым сигналом","difficulty":"2"},"material":"Схема дороги, вид сверху. Прямоугольники — автомобили, тёмная полоса — лобовое стекло (перед машины). Движение правостороннее. Синяя стрелка — автомобиль движется в эту сторону; автомобиль без стрелки стоит. Сине-красная полоса на крыше — включённые маячки.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 320\" width=\"480\" height=\"320\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"320\" fill=\"#f4f1e8\"/><rect x=\"180\" y=\"0\" width=\"120\" height=\"320\" rx=\"0\" fill=\"#9a9a92\" stroke=\"none\" stroke-width=\"0\"/><path d=\"M180 0 L180 320\" stroke=\"#777\" stroke-width=\"2\" fill=\"none\"/><path d=\"M300 0 L300 320\" stroke=\"#777\" stroke-width=\"2\" fill=\"none\"/><path d=\"M240 0 L240 320\" stroke=\"#fff\" stroke-width=\"3\" fill=\"none\" stroke-dasharray=\"18 12\"/><g transform=\"translate(270 180) rotate(0)\"><rect x=\"-11.0\" y=\"-20.0\" width=\"22\" height=\"40\" rx=\"5\" fill=\"#f2f2f2\" stroke=\"#222\" stroke-width=\"2\"/><rect x=\"-8.0\" y=\"-14.0\" width=\"16\" height=\"7\" rx=\"2\" fill=\"#2b2b2b\"/><rect x=\"-9.0\" y=\"-2\" width=\"9.0\" height=\"6\" fill=\"#1f4fd1\"/><rect x=\"0\" y=\"-2\" width=\"9.0\" height=\"6\" fill=\"#d12f2f\"/></g><path d=\"M270.0 156.0 L27