я общая', 'question', 0, 1, 'r6-sch-koap-09', 'r6-sch-koap-beacon', 'full', 2, 'koap', 'КоАП, ст. 9.27', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-sch-koap-09');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'hotspot', 'К перекрёстку приближается автомобиль с включёнными маячками и сиреной. Кто из водителей не предоставил ему преимущество?', '[]', '[]', '', 2, 20430, '{"meta":{"article":"КоАП, ст. 9.37","explanation":"Транспортному средству с включёнными маячками и сиреной нужно уступить дорогу; выезд перед ним — непредоставление преимущества.","quote":"Непредоставление преимущества транспортному средству с включенным проблесковым маячком синего цвета и(или) красного цвета и специальным звуковым сигналом","difficulty":"2"},"material":"Схема перекрёстка, вид сверху. Прямоугольники — автомобили, тёмная полоса — лобовое стекло (перед машины). Движение правостороннее. Синяя стрелка — автомобиль движется в эту сторону; автомобиль без стрелки стоит. Сине-красная полоса на крыше — включённые маячки.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 320\" width=\"480\" height=\"320\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"320\" fill=\"#f4f1e8\"/><rect x=\"0\" y=\"120\" width=\"480\" height=\"80\" rx=\"0\" fill=\"#9a9a92\" stroke=\"none\" stroke-width=\"0\"/><path d=\"M0 160 L480 160\" stroke=\"#fff\" stroke-width=\"3\" fill=\"none\" stroke-dasharray=\"18 12\"/><rect x=\"200\" y=\"0\" width=\"80\" height=\"320\" rx=\"0\" fill=\"#9a9a92\" stroke=\"none\" stroke-width=\"0\"/><path d=\"M240 0 L240 120\" stroke=\"#fff\" stroke-width=\"3\" fill=\"none\" stroke-dasharray=\"18 12\"/><path d=\"M240 200 L240 320\" stroke=\"#fff\" stroke-width=\"3\" fill=\"none\" stroke-dasharray=\"18 12\"/><g transform=\"translate(90 180) rotate(90)\"><rect x=\"-11.0\" y=\"-20.0\" width=\"22\" height=\"40\" rx=\"5\" fill=\"#f2f2f2\" stroke=\"#222\" stroke-width=\"2\"/><rect x=\"-8.0\" y=\"-14.0\" width=\"16\" height=\"7\" rx=\"2\" fill=\"#2b2b2b\"/><rect x=