INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'hotspot', 'Пешеход (красный кружок) переходит дорогу по пешеходному переходу. Какой водитель не предоставляет ему преимущество?', '[]', '[]', '', 1, 20440, '{"meta":{"article":"КоАП, ст. 9.40","explanation":"Водитель обязан уступить дорогу пешеходу, пересекающему проезжую часть; продолжать движение на переход с пешеходом нельзя.","quote":"Непредоставление преимущества в движении пешеходам и(или) велосипедистам, пересекающих проезжую часть","difficulty":"1"},"material":"Схема дороги, вид сверху. Прямоугольники — автомобили, тёмная полоса — лобовое стекло (перед машины). Движение правостороннее. Белые полосы поперёк дороги — пешеходный переход, светлые полосы по краям — тротуары. Синяя стрелка — автомобиль движется в эту сторону; автомобиль без стрелки стоит.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\" width=\"480\" height=\"270\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"270\" fill=\"#f4f1e8\"/><rect x=\"0\" y=\"40\" width=\"480\" height=\"30\" rx=\"0\" fill=\"#d9d2bf\" stroke=\"none\" stroke-width=\"0\"/><rect x=\"0\" y=\"190\" width=\"480\" height=\"30\" rx=\"0\" fill=\"#d9d2bf\" stroke=\"none\" stroke-width=\"0\"/><rect x=\"0\" y=\"70\" width=\"480\" height=\"120\" rx=\"0\" fill=\"#9a9a92\" stroke=\"none\" stroke-width=\"0\"/><path d=\"M0 130 L480 130\" stroke=\"#fff\" stroke-width=\"3\" fill=\"none\" stroke-dasharray=\"18 12\"/><path d=\"M0 70 L480 70\" stroke=\"#777\" stroke-width=\"2\" fill=\"none\"/><path d=\"M0 190 L480 190\" stroke=\"#777\" stroke-width=\"2\" fill=\"none\"/><rect x=\"220\" y=\"74\" width=\"40\" height=\"8\" rx=\"0\" fill=\"#fff\" stroke=\"none\" stroke-width=\"0\"/><rect x=\"220\" y=\"88\" width=\"40\" height=\"8\" rx=\"0\" fill=\"#fff\" stroke=\"none\" stroke-width=\"0\"/><rect x=\"220\" y=\"102\" width=\"40\" height=\"8\" rx=\"0\" fill=\"#fff\" stroke=\"none\" stroke-width=\"0\"/><rect x=\"220\" y=\"116\" width=\"40\" height=\"8\" rx=\"0\" fill=\"#fff\" stroke=\"none\" stroke-width=\"0\"/><rect x=\"220\" y=\"130\" width=\"40\" height=\"8\" rx=\"0\" fill=\"#fff\" stroke=\"none\" stroke-width=\"0\"/><rect x=\"220\" y=\"144\" width=\"40\" height=\"8\" rx=\"0\" fill=\"#fff\" stroke=\"none\" stroke-width=\"0\"/><rect x=\"220\" y=\"158\" width=\"40\" height=\"8\" rx=\"0\" fill=\"#fff\" stroke=\"none\" stroke-width=\"0\"/><rect x=\"220\" y=\"172\" width=\"40\" height=\"8\" rx=\"0\" fill=\"#fff\" stroke=\"none\" stroke-width=\"0\"/><circle cx=\"240\" cy=\"163\" r=\"6\" fill=\"#b0413e\" stroke=\"#222\" stroke-width=\"1.5\"/><path d=\"M240 155 L240.0 137.0\" stroke=\"#b0413e\" stroke-width=\"2\" fill=\"none\"/><path d=\"M240 130 L235.8 137.0 L244.2 137.0 Z\" fill=\"#b0413e\"/><g transform=\"translate(180 160) rotate(90)\"><rect x=\"-11.0\" y=\"-20.0\" width=\"22\" height=\"40\" rx=\"5\" fill=\"#3b6ea5\" stroke=\"#222\" stroke-width=\"2\"/><rect x=\"-8.0\" y=\"-14.0\" width=\"16\" height=\"7\" rx=\"2\" fill=\"#2b2b2b\"/></g><path d=\"M204.0 160.0 L221.0 160.0\" stroke=\"#1f4fd1\" stroke-width=\"3\" fill=\"none\"/><path d=\"M230.0 160.0 L221.0 154.6 L221.0 165.4 Z\" fill=\"#1f4fd1\"/><g transform=\"translate(286 100) rotate(270)\"><rect x=\"-11.0\" y=\"-20.0\" width=\"22\" height=\"40\" rx=\"5\" fill=\"#c99a2e\" stroke=\"#222\" stroke-width=\"2\"/><rect x=\"-8.0\" y=\"-14.0\" width=\"16\" height=\"7\" rx=\"2\" fill=\"#2b2b2b\"/></g><g transform=\"translate(400 160) rotate(90)\"><rect x=\"-11.0\" y=\"-20.0\" width=\"22\" height=\"40\" rx=\"5\" fill=\"#b0413e\" stroke=\"#222\" stroke-width=\"2\"/><rect x=\"-8.0\" y=\"-14.0\" width=\"16\" height=\"7\" rx=\"2\" fill=\"#2b2b2b\"/></g><path d=\"M424.0 160.0 L435.0 160.0\" stroke=\"#1f4fd1\" stroke-width=\"3\" fill=\"none\"/><path d=\"M444.0 160.0 L435.0 154.6 L435.0 165.4 Z\" fill=\"#1f4fd1\"/></svg>","alt":"До