INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'hotspot', 'Два автомобиля остановились у тротуара, из каждого выходит пассажир (красный кружок). Где высадка пассажира нарушает правила?', '[]', '[]', '', 1, 20450, '{"meta":{"article":"КоАП, ст. 9.7","explanation":"Посадка и высадка пассажиров со стороны проезжей части — правонарушение; выходить нужно на тротуар.","quote":"Посадка или высадка пассажиров со стороны проезжей части в нарушение правил дорожного движения","difficulty":"1"},"material":"Схема дороги, вид сверху. Прямоугольники — автомобили, тёмная полоса — лобовое стекло (перед машины). Движение правостороннее. Синяя стрелка — автомобиль движется в эту сторону; автомобиль без стрелки стоит. Светлые полосы по краям — тротуары, красная стрелка — куда выходит пассажир.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\" width=\"480\" height=\"270\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"270\" fill=\"#f4f1e8\"/><rect x=\"0\" y=\"40\" width=\"480\" height=\"30\" rx=\"0\" fill=\"#d9d2bf\" stroke=\"none\" stroke-width=\"0\"/><rect x=\"0\" y=\"190\" width=\"480\" height=\"30\" rx=\"0\" fill=\"#d9d2bf\" stroke=\"none\" stroke-width=\"0\"/><rect x=\"0\" y=\"70\" width=\"480\" height=\"120\" rx=\"0\" fill=\"#9a9a92\" stroke=\"none\" stroke-width=\"0\"/><path d=\"M0 130 L480 130\" stroke=\"#fff\" stroke-width=\"3\" fill=\"none\" stroke-dasharray=\"18 12\"/><path d=\"M0 70 L480 70\" stroke=\"#777\" stroke-width=\"2\" fill=\"none\"/><path d=\"M0 190 L480 190\" stroke=\"#777\" stroke-width=\"2\" fill=\"none\"/><g transform=\"translate(140 168) rotate(90)\"><rect x=\"-11.0\" y=\"-20.0\" width=\"22\" height=\"40\" rx=\"5\" fill=\"#3b6ea5\" stroke=\"#222\" stroke-width=\"2\"/><rect x=\"-8.0\" y=\"-14.0\" width=\"16\" height=\"7\" rx=\"2\" fill=\"#2b2b2b\"/></g><circle cx=\"140\" cy=\"138\" r=\"6\" fill=\"#b0413e\" stroke=\"#222\" stroke-width=\"1.5\"/><path d=\"M140 154 L140.0 152.0\" stroke=\"#b0413e\" stroke-width=\"2\" fill=\"none\"/><path d=\"M140 146 L136.4 152.0 L143.6 152.0 Z\" fill=\"#b0413e\"/><g transform=\"translate(300 168) rotate(90)\"><rect x=\"-11.0\" y=\"-20.0\" width=\"22\" height=\"40\" rx=\"5\" fill=\"#c99a2e\" stroke=\"#222\" stroke-width=\"2\"/><rect x=\"-8.0\" y=\"-14.0\" width=\"16\" height=\"7\" rx=\"2\" fill=\"#2b2b2b\"/></g><circle cx=\"300\" cy=\"202\" r=\"6\" fill=\"#b0413e\" stroke=\"#222\" stroke-width=\"1.5\"/><path d=\"M300 182 L300.0 188.0\" stroke=\"#b0413e\" stroke-width=\"2\" fill=\"none\"/><path d=\"M300 194 L303.6 188.0 L296.4 188.0 Z\" fill=\"#b0413e\"/><g transform=\"translate(390 100) rotate(270)\"><rect x=\"-11.0\" y=\"-20.0\" width=\"22\" height=\"40\" rx=\"5\" fill=\"#b0413e\" stroke=\"#222\" stroke-width=\"2\"/><rect x=\"-8.0\" y=\"-14.0\" width=\"16\" height=\"7\" rx=\"2\" fill=\"#2b2b2b\"/></g><path d=\"M366.0 100.0 L351.0 100.0\" stroke=\"#1f4fd1\" stroke-width=\"3\" fill=\"none\"/><path d=\"M342.0 100.0 L351.0 105.4 L351.0 94.6 Z\" fill=\"#1f4fd1\"/></svg>","alt":"Дорога, два стоящих у тротуара автомобиля с выходящими пассажирами и встречный автомобиль."}],"zones":[{"x":22.5,"y":45.9,"w":13.3,"h":23,"label":"Пассажир выходит со стороны проезжей части","id":"Mon0D8bv","correct":true},{"x":55.8,"y":56.3,"w":13.3,"h":23,"label":"Пассажир выходит на тротуар","id":"d3J4yDKG","correct":false},{"x":76.2,"y":31.5,"w":10,"h":11.1,"label":"Встречный автомобиль в движении","id":"HWJIQt4q","correct":false}],"show_labels":false,"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-sch-koap-12', 'r6-sch-koap-door', 'medium', 1, 'koap', 'КоАП, ст. 9.7', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-sch-koap-12');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'hotspot', 'Горизонтальная дорога — главная (жёлтый ромб), примыкающая снизу — второстепенная (знак «Уступите дорогу»). Найдите водителя, который не предоставил преимущество.', '[]', '[]', '', 2, 20460, '{"meta":{"article":"КоАП, ст. 9.39","explanation":"Выезжающий со второстепенной дороги обязан уступить транспортным средствам, движущимся по главной.","quote":"Непредоставление преимущества транспортным средствам, движущимся по главной дороге, а равно при выезде с прилегающей территории","difficulty":"2"},"material":"Схема Т-образного перекрёстка, вид сверху. Прямоугольники — автомобили, тёмная полоса — лобовое стекло (перед машины). Движение правостороннее. Синяя стрелка — автомобиль движется в эту сторону; автомобиль без стрелки стоит. Синий пунктир — траектория манёвра.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 300\" width=\"480\" height=\"300\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"300\" fill=\"#f4f1e8\"/><rect x=\"0\" y=\"100\" width=\"480\" height=\"80\" rx=\"0\" fill=\"#9a9a92\" stroke=\"none\" stroke-width=\"0\"/><path d=\"M0 140 L480 140\" stroke=\"#fff\" stroke-width=\"3\" fill=\"none\" stroke-dasharray=\"18 12\"/><rect x=\"210\" y=\"180\" width=\"60\" height=\"120\" rx=\"0\" fill=\"#9a9a92\" stroke=\"none\" stroke-width=\"0\"/><g transform=\"translate(120 74) rotate(45)\"><rect x=\"-12\" y=\"-12\" width=\"24\" height=\"24\" fill=\"#f5c400\" stroke=\"#222\" stroke-width=\"2\"/><rect x=\"-7\" y=\"-7\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\"/></g><path d=\"M285 208 L311 208 L298 230 Z\" fill=\"#fff\" stroke=\"#d12f2f\" stroke-width=\"4\"/><g transform=\"translate(110 160) rotate(90)\"><rect x=\"-11.0\" y=\"-20.0\" width=\"22\" height=\"40\" rx=\"5\" fill=\"#3b6ea5\" 