id = 'r6-sch-koap-13');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'hotspot', 'Автомагистраль, три полосы в одном направлении (цифры — номера полос, первая — крайняя правая). Отметьте все нарушения правил движения по автомагистрали.', '[]', '[]', '', 3, 20470, '{"meta":{"article":"КоАП, ст. 9.36","explanation":"На автомагистрали запрещено движение грузовых автомобилей далее второй полосы и движение задним ходом. Легковой в третьей полосе не нарушает.","quote":"движение по автомагистрали грузовых автомобилей далее второй полосы, и(или) движение по автомагистрали задним ходом","difficulty":"3"},"material":"Схема автомагистрали, вид сверху; все машины направлены вверх. Прямоугольники — автомобили, тёмная полоса — лобовое стекло (перед машины). Движение правостороннее. Синяя стрелка — направление движения (стрелка позади машины — движение задним ходом). Зелёные машины с тёмной кабиной — грузовые.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 320\" width=\"480\" height=\"320\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"320\" fill=\"#f4f1e8\"/><rect x=\"120\" y=\"0\" width=\"240\" height=\"320\" rx=\"0\" fill=\"#9a9a92\" stroke=\"none\" stroke-width=\"0\"/><path d=\"M120 0 L120 320\" stroke=\"#777\" stroke-width=\"2\" fill=\"none\"/><path d=\"M360 0 L360 320\" stroke=\"#777\" stroke-width=\"2\" fill=\"none\"/><path d=\"M200 0 L200 320\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\" stroke-dasharray=\"14 12\"/><path d=\"M280 0 L280 320\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\" stroke-dasharray=\"14 12\"/><text x=\"160\" y=\"20\" font-family=\"Arial, sans-serif\" font-size=\"14\" text-anchor=\"middle\" fill=\"#fff\" font-weight=\"bold\">3</text><text x=\"240\" y=\"20\" font-family=\"Arial, sans-serif\" font-size=\"14\" text-anchor=\"middle\" fill=\"#fff\" font-weight=\"bold\">2</text><text x=\"320\" y=\"20\" font-family=\"Arial, sans-serif\" font-size=\"14\" text-anchor=\"middle\" fill=\"#fff\" font-weight=\"bold\">1</text><g transform=\"translate(160 120) rotate(0)\"><rect x=\"-13.0\" y=\"-27.0\" width=\"26\" height=\"54\" rx=\"5\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><rect x=\"-13.0\" y=\"-27.0\" width=\"26\" height=\"16\" rx=\"4\" fill=\"#3a3a3a\" stroke=\"#222\" stroke-width=\"2\"/><rect x=\"-10.0\" y=\"-8\" width=\"20\" height=\"32\" fill=\"none\" stroke=\"#222\" stroke-width=\"1\"/></g><path d=\"M160.0 96.0 L160.0 87.0\" stroke=\"#1f4fd1\" stroke-width=\"3\" fill=\"none\"/><path d=\"M160.0 78.0 L154.6 87.0 L165.4 87.0 Z\" fill=\"#1f4fd1\"/><g transform=\"translate(320 200) rotate(0)\"><rect x=\"-13.0\" y=\"-27.0\" width=\"26\" height=\"54\" rx=\"5\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><rect x=\"-13.0\" y=\"-27.0\" width=\"26\" height=\"16\" rx=\"4\" fill=\"#3a3a3a\" stroke=\"#222\" stroke-width=\"2\"/><rect x=\"-10.0\" y=\"-8\" width=\"20\" height=\"32\" fill=\"none\" stroke=\"#222\" stroke-width=\"1\"/></g><path d=\"M320.0 176.0 L320.0 167.0\" stroke=\"#1f4fd1\" stroke-width=\"3\" fill=\"none\"/><path d=\"M320.0 158.0 L314.6 167.0 L325.4 167.0 Z\" fill=\"#1f4fd1\"/><g transform=\"translate(240 160) rotate(0)\"><rect x=\"-11.0\" y=\"-20.0\" width=\"22\" height=\"40\" rx=\"5\" fill=\"#b0413e\" stroke=\"#222\" stroke-width=\"2\"/><rect x=\"-8.0\" y=\"-14.0\" width=\"16\" height=\"7\" rx=\"2\" fill=\"#2b2b2b\"/></g><path d=\"M240.0 184.0 L240.0 197.0\" stroke=\"#1f4fd1\" stroke-width=\"3\" fill=\"none\"/><path d=\"M240.0 206.0 L245.4 197.0 L234.6 197.0 Z\" fill=\"#1f4fd1\"/><g transform=\"translate(160 260) rotate(0)\"><rect x=\"-11.0\" y=\"-20.0\" width=\"22\" height=\"40\" rx=\"5\" fill=\"#3b6ea5\" stroke=\"#222\" stroke-width=\"2\"/><rect x=\"-8.0\" y=\"-14.0\" width=\"16\" height=\"7\" rx=\"2\" fill=\"#2b2b2b\"/></g><path d=\"M160.0 236.0 L160.0 225.0\" stroke=\"#1f4fd1\" stroke-width=\"3\" fill=\"none\"/><path d=\"M160.0 216.0 L154.6 225.0 L165.4 225.0 Z\" fill=\"#1f4fd1\"/></svg>","alt":"Автомагистраль с тремя полосами, два грузовика и два легковых автомобиля."}],"zones":[{"x":28.3,"y":25.6,"w":10,"h":24.4,"label":"Грузовик в третьей полосе","id":"RlPg2gGf","correct":true},{"x":61.7,"y":50.6,"w":10,"h":24.4,"label":"Грузовик в первой полосе","id":"HHuBoKF","correct":false},{"x":46.2,"y":41.9,"w":7.5,"h":29.4,"label":"Легковой автомобиль движется задним ходом","id":"CanVqdsp","correct":true},{"x":30.2,"y":73.8,"w":6.2,"h":15,"label":"Легковой автомобиль в третьей полосе","id":"mp9lFkf7","correct":false}],"show_labels":false,"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-sch-koap-14', 'r6-sch-koap-motorway', 'vp', 3, 'koap', 'КоАП, ст. 9.36', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-sch-koap-14');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'hotspot', 'Отметьте водителя, который выполняет манёвр без сигнала указателем поворота.', '[]', '[]', '', 1, 20480, '{"meta":{"article":"КоАП, ст. 9.16","explanation":"Поворот, перестроение, начало движения и остановка требуют сигнала указателем поворота соответствующего направления.","quote":"Начало движения, перестроение, поворот (разворот) и остановка без использования сигнала световыми указателями поворота соответствующего направления","difficulty":"1"},"material":"Схема перекрёстка, вид сверху. Прямоугольники — автомобили, тёмная полоса — лобовое стекло (перед машины). Движение правостороннее. Оранжевые квадраты сбоку машины — включённый указатель поворота, синий пунктир — траектория.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 320\" width=\"480\" height=\"320\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"320\" fill=\"#f4f1e8\"/><rect x=\"0\" y=\"30\" width=\"480\" height=\"80\" rx=\"0\" fill=\"#9a9a92\" stroke=\"none\" stroke-width=\"0\"/><rect x=\"160\" y=\"0\" width=\"160\" height=\"320\" rx=\"0\" fill=\"#9a9a92\" stroke=\"none\" stroke-width=\"0\"/><path d=\"M160 0 L160 320\" stroke=\"#777\" stroke-width=\"2\" fill=\"none\"/><path d=\"M320 0 L320 320\" stroke=\"#777\" stroke-width=\"2\" fill=\"none\"/><path d=\"M240 0 L240 320\" stroke=\"#fff\" stroke-width=\"3\" fill=\"none\"/><path d=\"M280 0 L280 320\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\" stroke-dasharray=\"14 12\"/><rect x=\"160\" y=\"30\" width=\"160\" height=\"80\" rx=\"0\" fill=\"#9a9a92\" stroke=\"none\" stroke-width=\"0\"/><path d=\"M240 120 L320 120\" stroke=\"#fff\" stroke-width=\"3\" fill=\"none\"/><g transform=\"translate(300 160) rotate(0)\"><rect x=\"-11.0\" y=\"-20.0\" width=\"22\" height=\"40\" rx=\"5\" fill=\"#3b6ea5\" stroke=\"#222\" stroke-width=\"2\"/><rect x=\"-8.0\" y=\"-14.0\" width=\"16\" height=\"7\" rx=\"2\" fill=\"#2b2b2b\"/><rect x=\"9.0\" y=\"-19.0\" width=\"6\" height=\"6\" fill=\"#ff9f1a\" stroke=\"#222\" stroke-width=\"1\"/><rect x=\"9.0\" y=\"13.0\" width=\"6\" height=\"6\" fill=\"#ff9f1a\" stroke=\"#222\" stroke-width=\"1\"/></g><path d=\"M300 136 Q302 75 360 72\" stroke=\"#1f4fd1\" stroke-width=\"3\" fill=\"none\" stroke-dasharray=\"7 5\"/><path d=\"M352 72 L363.0 72.0\" stroke=\"#1f4fd1\" stroke-width=\"3\" fill=\"none\"/><path d=\"M372 72 L363.0 66.6 L363.0 77.4 Z\" fill=\"#1f4fd1\"/><g transform=\"translate(260 170) rotate(0)\"><rect x=\"-11.0\" y=\"-20.0\" width=\"22\" height=\"40\" rx=\"5\" fill=\"#b0413e\" stroke=\"#222\" stroke-width=\"2\"/><rect x=\"-8.0\" y=\"-14.0\" width=\"16\" height=\"7\" rx=\"2\" fill=\"#2b2b2b\"/></g><path d=\"M260 146 Q262 88 150 82\" stroke=\"#1f4fd1\" stroke-width=\"3\" fill=\"none\" stroke-dasharray=\"7 5\"/><path d=\"M160 82 L149.0 82.0\" stroke=\"#1f4fd1\" stroke-width=\"3\" fill=\"none\"/><path d=\"M140 82 L149.0 87.4 L149.0 76.6 Z\" fill=\"#1f4fd1\"/><g transform=\"translate(300 270) rotate(0)\"><rect x=\"-11.0\" y=\"-20.0\" width=\"22\" height=\"40\" rx=\"5\" fill=\"#c99a2e\" stroke=\"#222\" stroke-width=\"2\"/><rect x=\"-8.0\" y=\"-14.0\" width=\"16\" height=\"7\" rx=\"2\" fill=\"#2b2b2b\"/><rect x=\"-15.0\" y=\"-19.0\" width=\"6\" height=\"6\" fill=\"#ff9f1a\" stroke=\"#222\" stroke-width=\"1\"/><rect x=\"-15.0\" y=\"13.0\" width=\"6\" height=\"6\" fill=\"#ff9f1a\" stroke=\"#222\" stroke-width=\"1\"/></g><path d=\"M300 246 Q300 222 262 206\" stroke=\"#1f4fd1\" stroke-width=\"3\" fill=\"none\" stroke-dasharray=\"7 5\"/></svg>","alt":"Перекрёсток и три автомобиля с траекториями манёвров."}],"zones":[{"x":59.2,"y":42.2,"w":6.7,"h":15.6,"label":"Поворачивает направо с правым указателем","id":"0XsIYKr","correct":false},{"x":50.8,"y":45.3,"w":6.7,"h":15.6,"label":"Поворачивает налево без указателя поворота","id":"Kjn8n9P9","correct":true},{"x":59.2,"y":76.6,"w":6.7,"h":15.6,"label":"Перестраивается влево с левым указателем","id":"U77NW1G","correct":false}],"show_labels":false,"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-sch-koap-15', 'r6-sch-koap-blink', 'medium', 1, 'koap', 'КоАП, ст. 9.16', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-sch-koap-15');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте ситуации на схеме с нарушениями.', '[]', '[]', '', 2, 20490, '{"meta":{"article":"КоАП, ст. 9.14, 9.25, 9.30","explanation":"А — стоянка на переходе, Б — движение по обочине, В — проезд на красный, Г — пересечение организованной колонны.","quote":"Остановка или стоянка транспортных средств на пешеходном переходе … Движение по разделительным полосам и обочинам … Проезд на красный сигнал светофора … пересечение организованной транспортной или пешей колонны","difficulty":"2"},"material":"Четыре ситуации, вид сверху. Прямоугольники — автомобили, тёмная полоса — лобовое стекло (перед машины). Движение правостороннее. Синяя стрелка — автомобиль движется в эту сторону; автомобиль без стрелки стоит. В ситуации В светофор горит красным; в ситуации Г зелёные машины — грузовики организованной колонны.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 320\" width=\"480\" height=\"320\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"320\" fill=\"#f4f1e8\"/><rect x=\"4\" y=\"4\" width=\"232\" height=\"152\" rx=\"6\" fill=\"#ebe5d3\" stroke=\"#555\" stroke-width=\"2\"/><text x=\"22\" y=\"28\" font-family=\"Arial, sans-serif\" font-size=\"18\" text-anchor=\"middle\" fill=\"#222\" font-weight=\"bold\">А</text><rect x=\"244\" y=\"4\" width=\"232\" height=\"152\" rx=\"6\" fill=\"#ebe5d3\" stroke=\"#555\" stroke-width=\"2\"/><text x=\"262\" y=\"28\" font-family=\"Arial, sans-serif\" font-size=\"18\" text-anchor=\"middle\" fill=\"#222\" font-weight=\"bold\">Б</text><rect x=\"4\" y=\"164\" width=\"232\" height=\"152\" rx=\"6\" fill=\"#ebe5d3\" stroke=\"#555\" stroke-width=\"2\"/><text x=\"22\" y=\"188\" font-family=\"Arial, sans-serif\" font-size=\"18\" text-anchor=\"middle\" fill=\"#222\" font-weight=\"bold\">В</text><rect x=