ht=\"7\" rx=\"2\" fill=\"#2b2b2b\"/></g><path d=\"M365.0 211.0 L365.0 216.0\" stroke=\"#1f4fd1\" stroke-width=\"3\" fill=\"none\"/><path d=\"M365.0 207.0 L359.6 216.0 L370.4 216.0 Z\" fill=\"#1f4fd1\"/></svg>","alt":"Четыре мини-схемы дорожных ситуаций, обозначенные буквами А, Б, В, Г."}],"pairs":[{"l":{"id":"MpikZ7n","text":"А"},"r":{"id":"GybaztiN","text":"Остановка на пешеходном переходе"}},{"l":{"id":"oCE07Z54","text":"Б"},"r":{"id":"sLaUrWxn","text":"Движение по обочине"}},{"l":{"id":"cJrqlL7N","text":"В"},"r":{"id":"mUVB0eY","text":"Проезд на красный сигнал светофора"}},{"l":{"id":"Fv7TpEWy","text":"Г"},"r":{"id":"BmescRcw","text":"Пересечение организованной колонны"}}],"distractors":[{"id":"BrP8MWw","text":"Препятствование обгону"},{"id":"Cyp0kH5E","text":"Движение задним ходом по автомагистрали"}],"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-sch-koap-16', 'r6-sch-koap-match', 'medium', 2, 'koap', 'КоАП, ст. 9.14, 9.25, 9.30', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-sch-koap-16');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'hotspot', 'Отметьте охраняемые территории войсковой части (не закрытые, а именно охраняемые).', '[]', '[]', '', 2, 20500, '{"meta":{"article":"ФЗ о закрытых и охраняемых территориях, ст. 20, ч. 20.2","explanation":"Охраняемые территории: КПП войсковых частей и парковочные комплексы перед ними, военные комиссариаты, подъездной участок к КПП части.","quote":"20.2. Охраняемыми территориями являются: … 1) контрольно-пропускные пункты войсковых частей и парковочные комплексы перед ними; … 3) подъездной участок к КПП на территорию Войсковой части №12132.","difficulty":"2"},"material":"Условная схема войсковой части, вид сверху: толстая линия — сплошной забор по периметру, ниже КПП — парковка и подъездная дорога, зелёное — местность вокруг.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 340\" width=\"480\" height=\"340\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"340\" fill=\"#cfdcb4\"/><rect x=\"60\" y=\"18\" width=\"360\" height=\"222\" rx=\"0\" fill=\"#e6e1d0\" stroke=\"#555\" stroke-width=\"4\"/><rect x=\"100\" y=\"50\" width=\"120\" height=\"70\" rx=\"0\" fill=\"#d9cfb4\" stroke=\"#555\" stroke-width=\"2\"/><text x=\"160\" y=\"90\" font-family=\"Arial, sans-serif\" font-size=\"13\" text-anchor=\"middle\" fill=\"#222\">Штаб</text><rect x=\"280\" y=\"60\" width=\"110\" height=\"60\" rx=\"0\" fill=\"#d9cfb4\" stroke=\"#555\" stroke-width=\"2\"/><text x=\"335\" y=\"95\" font-family=\"Arial, sans-serif\" font-size=\"13\" text-anchor=\"middle\" fill=\"#222\">Склад</text><rect x=\"200\" y=\"232\" width=\"80\" height=\"18\" rx=\"0\" fill=\"#bbb\" stroke=\"#222\" stroke-width=\"2\"/><text x=\"240\" y=\"246\" font-family=\"Arial, sans-serif\" font-size=\"12\" text-anchor=\"middle\" fill=\"#222\" font-weight=\"bold\">КПП</text><rect x=\"150\" y=\"254\" width=\"180\" height=\"40\" rx=\"0\" fill=\"#a8a49a\" stroke=\"#555\" stroke-width=\"2\"/><path d=\"M180 254 L180 280\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/><path d=\"M210 254 L210 280\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/><path d=\"M240 254 L240 280\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/><path d=\"M270 254 L270 280\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/><path d=\"M300 254 L300 280\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/><rect x=\"215\" y=\"294\" width=\"50\" height=\"46\" rx=\"0\" fill=\"#9a9a92\" stroke=\"none\" stroke-width=\"0\"/></svg>","alt":"Условная схема войсковой части с забором, зданиями, КПП, парковкой и подъездом."}],"zones":[{"x":22.5,"y":16.5,"w":21.7,"h":17.1,"label":"Крыша здания внутри забора","id":"4Dzruj0S","correct":false},{"x":50,"y":44.1,"w":31.2,"h":20.6,"label":"Двор внутри забора","id":"y4gsFEM","correct":false},{"x":31.2,"y":67.1,"w":37.5,"h":19.4,"label":"КПП и парковка перед ним","id":"OReg2Md9","correct":true},{"x":44.8,"y":87.1,"w":10.4,"h":12.4,"label":"Подъездной участок к КПП","id":"kbhBeJl0","correct":true},{"x":0.8,"y":76.5,"w":25,"h":22.4,"label":"Поле в стороне от части","id":"XCJbJ3q","correct":false}],"show_labels":false,"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-sch-fzt-01', 'r6-sch-fzt-vch', 'medium', 2, 'fz_territorii', 'ФЗ о закрытых и охраняемых территориях, ст. 20, ч. 20.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-sch-fzt-01');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'hotspot', 'Какие участки на схеме закрыты для общего пользования и посещения? Отметьте все.', '[]', '[]', '', 2, 20510, '{"meta":{"article":"ФЗ о закрытых и охраняемых территориях, ст. 20, ч. 20.1","explanation":"Закрыта вся территория внутри сплошного забора: здания, крыши, иные объекты и пространство. КПП с парковкой и подъезд — охраняемые.","quote":"20.1. Территории войсковых частей, огражденные сплошным периметром забора, то есть вся территория, здания, крыши, иные объекты и пространство в закрытой сплошным периметром забора территории","difficulty":"2"},"material":"Условная схема войсковой части, вид сверху: толстая линия — сплошной забор по периметру, ниже КПП — парковка и подъездная дорога, зелёное — местность вокруг.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 340\" width=\"480\" height=\"340\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"340\" fill=\"#cfdcb4\"/><rect x=\"60\" y=\"18\" width=\"360\" height=\"222\" rx=\"0\" fill=\"#e6e1d0\" stroke=\"#555\" stroke-width=\"4\"/><rect x=\"100\" y=\"50\" width=\"120\" height=\"70\" rx=\"0\" fill=\"#d9cfb4\" stroke=\"#555\" stroke-width=\"2\"/><text x=\"160\" y=\"90\" font-family=\"Arial, sans-serif\" font-size=\"13\" text-anchor=\"middle\" fill=\"#222\">Штаб</text><rect x=\"280\" y=\"60\" width=\"110\" height=\"60\" rx=\"0\" fill=\"#d9cfb4\" stroke=\"#555\" stroke-width=\"2\"/><text x=\"335\" y=\"95\" font-family=\"Arial, sans-serif\" font-size=\"13\" text-anchor=\"middle\" fill=\"#222\">Склад</text><rect x=\"200\" y=\"232\" width=\"80\" height=\"18\" rx=\"0\" fill=\"#bbb\" stroke=\"#222\" stroke-width=\"2\"/><text x=\"240\" y=\"246\" font-family=\"Arial, sans-serif\" font-size=\"12\" text-anchor=\"middle\" fill=\"#222\" font-weight=\"bold\">КПП</text><rect x=\"150\" y=\"254\" width=\"180\" height=\"40\" rx=\"0\" fill=\"#a8a49a\" stroke=\"#555\" stroke-width=\"2\"/><path d=\"M180 254 L180 280\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/><path d=\"M210 254 L210 280\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/><path d=\"M240 254 L240 280\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/><path d=\"M270 254 L270 280\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/><path d=\"M300 254 L300 280\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/><rect x=\"215\" y=\"294\" width=\"50\" height=\"46\" rx=\"0\" fill=\"#9a9a92\" stroke=\"none\" stroke-width=\"0\"/></svg>","alt":"Условная схема войсковой части с забором, зданиями, КПП, парковкой и подъездом."}],"zones":[{"x":22.5,"y":16.5,"w":21.7,"h":17.1,"label":"Крыша здания внутри забора","id":"V8BYDZeC","correct":true},{"x":50,"y":44.1,"w":31.2,"h":20.6,"label":"Двор внутри забора","id":"7odVCE8q","correct":true},{"x":31.2,"y":67.1,"w":37.5,"h":19.4,"label":"КПП и парковка перед ним","id":"GjGn4o6","correct":false},{"x":44.8,"y":87.1,"w":10.4,"h":12.4,"label":"Подъездной участок к КПП","id":"ZjAWh4ag","correct":false},{"x":0.8,"y":76.5,"w":25,"h":22.4,"label":"Поле в стороне от части","id":"xrDIBBt4","correct":false}],"show_labels":false,"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-sch-fzt-02', 'r6-sch-fzt-vch', 'full', 2, 'fz_territorii', 'ФЗ о закрытых и охраняемых территориях, ст. 20, ч. 20.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-sch-fzt-02');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'hotspot', 'Отметьте участки, которые относятся к охраняемой территории учреждения исполнения наказаний.', '[]', '[]', '', 3, 20520, '{"meta":{"article":"ФЗ о закрытых и охраняемых территориях, ст. 24, ч. 24.2","explanation":"Охраняемая территория — огороженная парковка и прилегающая территория в 15 м от ограждения. Сама территория учреждения — закрытая, 25 м — за пределами прилегающей.","quote":"1) огражденная парковка учреждений исполнения наказаний; … Прилегающей территорией считается территория отступающая на 15 метров от ограждений учреждения исполнения наказаний.","difficulty":"3"},"material":"Условная схема, вид сверху: толстая рамка — ограждение учреждения, пунктир — огороженная парковка, красные точки — места на местности с расстоянием до ограждения.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 300\" width=\"480\" height=\"300\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"300\" fill=\"#cfdcb4\"/><rect x=\"150\" y=\"40\" width=\"180\" height=\"150\" rx=\"0\" fill=\"#cfc8b4\" stroke=\"#333\" stroke-width=\"5\"/><text x=\"240\" y=\"120\" font-family=\"Arial, sans-serif\" font-size=\"13\" text-anchor=\"middle\" fill=\"#222\">учреждение</text><text x=\"240\" y=\"136\" font-family=\"Arial, sans-serif\" font-size=\"12\" text-anchor=\"middle\" fill=\"#222\">исполнения наказаний</text><rect x=\"30\" y=\"70\" width=\"90\" height=\"90\" rx=\"0\" fill=\"#a8a49a\" stroke=\"#333\" stroke-width=\"3\" stroke-dasharray=\"6 4\"/><text x=\"75\" y=\"120\" font-family=\"Arial, sans-serif\" font-size=\"12\" text-anchor=\"middle\" fill=\"#222\">парковка</text><circle cx=\"390\" cy=\"115\" r=\"8\" fill=\"#b0413e\"/><circle cx=\"240\" cy=\"246\" r=\"8\" fill=\"#b0413e\"/><path d=\"M330 140 L390 140\" stroke=\"#222\" stroke-width=\"1.5\" fill=\"none\"/><text x=\"360\" y=\"158\" font-family=\"Arial, sans-serif\" font-size=\"12\" text-anchor=\"middle\" fill=\"#222\">10 м</text><path d=\"M270 190 L270 270\" stroke=\"#222\" stroke-width=\"1.5\" fill=\"none\"/><text x=\"300\" y=\"240\" font-family=\"Arial, sans-serif\" font-size=\"12\" text-anchor=\"middle\" fill=\"#222\">25 м</text></svg>","alt":"Учреждение исполнения наказаний, парковка и две точки на разном расстоянии от ограждения."}],"zones":[{"x":35.4,"y":20,"w":29.2,"h":36.7,"label":"Территория за ограждением","id":"lvZ19xI","correct":false},{"x":77.1,"y":31.7,"w":8.3,"h":13.3,"label":"Точка в 10 м от ограждения","id":"VfrMRvfC","correct":true},{"x":45.8,"y":75.3,"w":8.3,"h":13.3,"label":"Точка в 25 м от ограждения","id":"1dbnRRnk","correct":false},{"x":6.2,"y":23.3,"w":18.8,"h":30,"label":"Огороженная парковка учреждения","id":"HmQE1Xgt","correct":true}],"show_labels":false,"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-sch-fzt-03', 'r6-sch-fzt-uin', 'vp', 3, 'fz_territorii', 'ФЗ о закрытых и охраняемых территориях, ст. 24, ч. 24.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-sch-fzt-03');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'hotspot', 'Отметьте все участки УВД по ЦАО, закрытые для общего пользования и посещения.', '[]', '[]', '', 3, 20530, '{"meta":{"article":"ФЗ о закрытых и охраняемых территориях, ст. 14, ч. 14.1","explanation":"Закрыты: фронтальная зона и задний двор, все помещения и кабинеты (кроме холла), КПЗ, внутренняя парковка.","quote":"1) фронтальная зона и задний двор УВД по ЦАО; … 2) все помещения и кабинеты УВД по ЦАО, за исключением холла; … 3) камера предварительного заключения УВД по ЦАО; … 7) внутренняя парковка УВД по ЦАО.","difficulty":"3"},"material":"Условная схема территории УВД по ЦАО, вид сверху: участки подписаны, толстая рамка — здание.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 320\" width=\"480\" height=\"320\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"320\" fill=\"#cfdcb4\"/><rect x=\"130\" y=\"10\" width=\"220\" height=\"50\" rx=\"0\" fill=\"#ddd6c2\" stroke=\"#555\" stroke-width=\"2\"/><text x=\"240.0\" y=\"40.0\" font-family=\"Arial, sans-serif\" font-size=\"12\" text-anchor=\"middle\" fill=\"#222\">Задний двор</text><rect x=\"360\" y=\"10\" width=\"110\" height=\"110\" rx=\"0\" fill=\"#a8a49a\" stroke=\"#555\" stroke-width=\"2\"/><text x=\"415.0\" y=\"63.0\" font-family=\"Arial, sans-serif\" font-size=\"12\" text-anchor=\"middle\" fill=\"#222\">Внутренняя</text><text x=\"415.0\" y=\"78.0\" font-family=\"Arial, sans-serif\" font-size=\"12\" text-anchor=\"middle\" fill=\"#222\">парковка</text><rect x=\"130\" y=\"66\" width=\"105\" height=\"80\" rx=\"0\" fill=\"#d9cfb4\" stroke=\"#555\" stroke-width=\"2\"/><text x=\"182.5\" y=\"111.0\" font-family=\"Arial, sans-serif\" font-size=\"12\" text-anchor=\"middle\" fill=\"#222\">Кабинеты</text><rect x=\"245\" y=\"66\" width=\"105\" height=\"80\" rx=\"0\" fill=\"#d9cfb4\" stroke=\"#555\" stroke-width=\"2\"/><text x=\"297.5\" y=\"111.0\" font-family=\"Arial, sans-serif\" font-size=\"12\" text-anchor=\"middle\" fill=\"#222\">КПЗ</text><rect x=\"130\" y=\"150\" width=\"220\" height=\"50\" rx=\"0\" fill=\"#efe4c4\" stroke=\"#555\" stroke-width=\"2\"/><text x=\"240.0\" y=\"180.0\" font-family=\"Arial, sans-serif\" font-size=\"12\" text-anchor=\"middle\" fill=\"#222\">Холл</text><rect x=\"130\" y=\"206\" width=\"220\" height=\"44\" rx=\"0\" fill=\"#ddd6c2\" stroke=\"#555\" stroke-width=\"2\"/><text x=\"240.0\" y=\"233.0\" font-family=\"Arial, sans-serif\" font-size=\"12\" text-anchor=\"middle\" fill=\"#222\">Фронтальная зона</text><rect x=\"10\" y=\"206\" width=\"110\" height=\"104\" rx=\"0\" fill=\"#a8a49a\" stroke=\"#555\" stroke-width=\"2\"/><text x=\"65.0\" y=\"256.0\" font-family=\"Arial, sans-serif\" font-size=\"12\" text-anchor=\"middle\" fill=\"#222\">Внешняя</text><text x=\"65.0\" y=\"271.0\" font-family=\"Arial, sans-serif\" font-size=\"12\" text-anchor=\"middle\" fill=\"#222\">парковка</text><rect x=\"360\" y=\"206\" width=\"110\" height=\"104\" rx=\"0\" fill=\"#9a9a92\" stroke=\"#555\" stroke-width=\"2\"/><text x=\"415.0\" y=\"256.0\" font-family=\"Arial, sans-serif\" font-size=\"12\" text-anchor=\"middle\" fill=\"#222\">Подъезд к</text><text x=\"415.0\" y=\"271.0\" font-family=\"Arial, sans-serif\" font-size=\"12\" text-anchor=\"middle\" fill=\"#222\">КПП</text><rect x=\"130\" y=\"66\" width=\"220\" height=\"134\" rx=\"0\" fill=\"none\" stroke=\"#333\" stroke-width=\"4\"/></svg>","alt":"Условная схема УВД по ЦАО с восемью подписанными участками."}],"zones":[{"x":27.1,"y":3.1,"w":45.8,"h":15.6,"label":"Задний двор","id":"AssnVGX2","correct":true},{"x":75,"y":3.1,"w":22.9,"h":34.4,"label":"Внутренняя парковка","id":"kSgP8GUe","correct":true},{"x":27.1,"y":20.6,"w":21.9,"h":25,"label":"Кабинеты","id":"JuazcCO5","correct":true},{"x":51,"y":20.6,"w":21.9,"h":25,"label":"КПЗ","id":"taMj0PSq","correct":true},{"x":27.1,"y":46.9,"w":45.8,"h":15.6,"label":"Холл","id":"Et0xwNsn","correct":false},{"x":27.1,"y":64.4,"w":45.8,"h":13.8,"label":"Фронтальная зона","id":"xDHFZQlO","correct":true},{"x":2.1,"y":64.4,"w":22.9,"h":32.5,"label":"Внешняя парковка","id":"gBTB2RT7","correct":false},{"x":75,"y":64.4,"w":22.9,"h":32.5,"label":"Подъезд к КПП","id":"FWsbgFJ","correct":false}],"show_labels":false,"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-sch-fzt-04', 'r6-sch-fzt-uvd', 'full', 3, 'fz_territorii', 'ФЗ о закрытых и охраняемых территориях, ст. 14, ч. 14.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-sch-fzt-04');
