INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'hotspot', 'На условной карте зоны раскрашены так же, как в приложении к Федеральному закону. Отметьте зону строгого режима.', '[]', '[]', '', 1, 20550, '{"meta":{"article":"ФЗ о закрытых и охраняемых территориях, ст. 1, ч. 1.1, пп. 4–6","explanation":"Зона строгого режима отмечается красным цветом; жёлтым — зона ограниченного доступа, зелёная — зона общего порядка.","quote":"6) зона строгого режима, отмеченная в приложении к настоящему Федеральному закону красным цветом - закрытая для общего пользования территория для посещения.","difficulty":"1"},"material":"Условная карта с цветными зонами.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 280\" width=\"480\" height=\"280\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"280\" fill=\"#efeadb\"/><path d=\"M30 40 Q120 10 200 50 L190 160 Q100 190 40 150 Z\" stroke=\"#333\" stroke-width=\"2\" fill=\"#7fbf6a\"/><path d=\"M220 40 L330 30 L350 140 L240 170 Z\" stroke=\"#333\" stroke-width=\"2\" fill=\"#d64a3e\"/><path d=\"M360 60 Q440 40 460 120 L420 250 L330 230 Z\" stroke=\"#333\" stroke-width=\"2\" fill=\"#f0cf3a\"/><path d=\"M60 200 L200 190 L230 260 L70 265 Z\" stroke=\"#333\" stroke-width=\"2\" fill=\"#9e9e9e\"/></svg>","alt":"Условная карта с зелёной, красной, жёлтой и серой зонами."}],"zones":[{"x":10.4,"y":17.9,"w":27.1,"h":35.7,"label":"Зелёная зона","id":"78dITyhD","correct":false},{"x":50,"y":17.9,"w":19.8,"h":35.7,"label":"Красная зона","id":"yvqFIazy","correct":true},{"x":75,"y":28.6,"w":16.7,"h":50,"label":"Жёлтая зона","id":"NEUnkiW","correct":false},{"x":16.7,"y":71.4,"w":27.1,"h":20.7,"label":"Серая зона (не обозначена законом)","id":"63leAnA6","correct":false}],"show_labels":false,"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-sch-fzt-06', 'r6-sch-fzt-colors', 'medium', 1, 'fz_territorii', 'ФЗ о закрытых и охраняемых территориях, ст. 1, ч. 1.1, пп. 4–6', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-sch-fzt-06');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Военнослужащий обращён лицом вверх (серая стрелка). Сопоставьте команды с направлением, куда он будет обращён после их выполнения.', '[]', '[]', '', 2, 20560, '{"meta":{"article":"СУ, п. 23","explanation":"Налево — 1/4 круга влево, направо — 1/4 круга вправо, кругом — 1/2 круга, пол-оборота налево — 1/8 круга влево.","quote":"23. Повороты на месте выполняются по командам: \"Напра-ВО\", \"Пол-оборота напра-ВО\", \"Нале-ВО\", \"Пол-оборота нале-ВО\", \"Кру-ГОМ\". … Повороты кругом (на 1/2 круга), налево (на 1/4 круга), пол-оборота налево (на 1/8 круга) производятся в сторону левой руки","difficulty":"2"},"material":"Схема: военнослужащий, вид сверху. Фиолетовые стрелки с буквами — направления. Кружки — военнослужащие, уголок на кружке показывает, куда военнослужащий обращён лицом.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 320\" width=\"480\" height=\"320\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"320\" fill=\"#f4f1e8\"/><g transform=\"translate(240 170) rotate(0)\"><circle cx=\"0\" cy=\"0\" r=\"16\" fill=\"#4a6b3a\" stroke=\"#222\" stroke-width=\"2\"/><path d=\"M-6 -11 L0 -19 L6 -11\" stroke=\"#fff\" stroke-width=\"2\" fill=\"none\"/></g><path d=\"M210.0 170.0 L140.0 170.0\" stroke=\"#7a5c99\" stroke-width=\"3\" fill=\"none\"/><path d=\"M130.0 170.0 L140.0 176.0 L140.0 164.0 Z\" fill=\"#7a5c99\"/><text x=\"110\" y=\"176\" font-family=\"Arial, sans-serif\" font-size=\"18\" text-anchor=\"middle\" fill=\"#222\" font-weight=\"bold\">А</text><path d=\"M270.0 170.0 L340.0 170.0\" stroke=\"#7a5c99\" stroke-width=\"3\" fill=\"none\"/><path d=\"M350.0 170.0 L340.0 164.0 L340.0 176.0 Z\" fill=\"#7a5c99\"/><text x=\"370\" y=\"176\" font-family=\"Arial, sans-serif\" font-size=\"18\" text-anchor=\"middle\" fill=\"#222\" font-weight=\"bold\">Б</text><path d=\"M240.0 200.0 L240.0 270.0\" stroke=\"#7a5c99\" stroke-width=\"3\" fill=\"none\"/><path d=\"M240.0 280.0 L246.0 270.0 L234.0 270.0 Z\" fill=\"#7a5c99\"/><text x=\"240\" y=\"306\" font-family=\"Arial, sans-serif\" font-size=\"18\" text-anchor=\"middle\" fill=\"#222\" font-weight=\"bold\">В</text><path d=\"M218.8 148.8 L169.3 99.3\" stroke=\"#7a5c99\" stroke-width=\"3\" fill=\"none\"/><path d=\"M162.2 92.2 L165.0 103.5 L173.5 95.0 Z\" fill=\"#7a5c99\"/><text x=\"148\" y=\"84\" font-family=\"Arial, sans-serif\" font-size=\"18\" text-anchor=\"middle\" fill=\"#222\" font-weight=\"bold\">Г</text><path d=\"M240.0 140.0 L240.0 70.0\" stroke=\"#8a8a8a\" stroke-width=\"3\" fill=\"none\"/><path d=\"M240.0 60.0 L234.0 70.0 L246.0 70.0 Z\" fill=\"#8a8a8a\"/><text x=\"254\" y=\"46\" font-family=\"Arial, sans-serif\" font-size=\"12\" text-anchor=\"start\" fill=\"#666\">сейчас</text></svg>","alt":"Военнослужащий, вид сверху, и стрелки-направления с буквами А, Б, В, Г."}],"pairs":[{"l":{"id":"qj1CcLzv","text":"«Нале-ВО»"},"r":{"id":"yLx7K4w","text":"А"}},{"l":{"id":"L1So3aZ9","text":"«Напра-ВО»"},"r":{"id":"Hr55aEa2","text":"Б"}},{"l":{"id":"wb0m5O74","text":"«Кру-ГОМ»"},"r":{"id":"upLwxRpO","text":"В"}},{"l":{"id":"WZBJd7Z1","text":"«Пол-оборота нале-ВО»"},"r":{"id":"aC9CTALE","text":"Г"}}],"distractors":[{"id":"QdZ6BZA5","text":"Остаётся обращён вверх"}],"partial":false}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-sch-su-26', 'r6-sch-su-turn3', 'simple', 2, 'su', 'СУ, п. 23', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-sch-su-26');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Гражданин стоит в точке Х — в 12 м от ограждения учреждения исполнения наказаний. К какой территории относится это место?', '[{"id":"o9UAqJS","text":"Охраняемая территория (прилегающая)"},{"id":"PZvaYric","text":"Закрытая территория учреждения"},{"id":"XsruSx2N","text":"Не относится к учреждению"},{"id":"bIGda58A","text":"Зона ограниченного доступа (жёлтая)"}]', '["o9UAqJS"]', '', 2, 20570, '{"meta":{"article":"ФЗ о закрытых и охраняемых территориях, ст. 24, ч. 24.2","explanation":"Прилегающая территория — 15 м от ограждений, она относится к охраняемой территории учреждения.","quote":"2) прилегающая к учреждению исполнения наказаний территория. Прилегающей территорией считается территория отступающая на 15 метров от ограждений учреждения исполнения наказаний.","difficulty":"2"},"material":"Условная схема, вид сверху: толстая рамка — ограждение учреждения, красная точка Х — место, где стоит гражданин.","media":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 260\" width=\"480\" height=\"260\"><rect x=\"0\" y=\"0\" width=\"480\" height=\"260\" fill=\"#cfdcb4\"/><rect x=\"140\" y=\"40\" width=\"200\" height=\"150\" rx=\"0\" fill=\"#cfc8b4\" stroke=\"#333\" stroke-width=\"5\"/><text x=\"240\" y=\"112\" font-family=\"Arial, sans-serif\" font-size=\"13\" text-anchor=\"middle\" fill=\"#222\">учреждение</text><text x=\"240\" y=\"128\" font-family=\"Arial, sans-serif\" font-size=\"12\" text-anchor=\"middle\" fill=\"#222\">исполнения наказаний</text><circle cx=\"412\" cy=\"115\" r=\"9\" fill=\"#b0413e\"/><text x=\"412\" y=\"98\" font-family=\"Arial, sans-serif\" font-size=\"14\" text-anchor=\"middle\" fill=\"#222\" font-weight=\"bold\">Х</text><path d=\"M340 140 L412 140\" stroke=\"#222\" stroke-width=\"1.5\" fill=\"none\"/><path d=\"M340 133 L340 147\" stroke=\"#222\" stroke-width=\"1.5\" fill=\"none\"/><path d=\"M412 133 L412 147\" stroke=\"#222\" stroke-width=\"1.5\" fill=\"none\"/><text x=\"376\" y=\"158\" font-family=\"Arial, sans-serif\" font-size=\"12\" text-anchor=\"middle\" fill=\"#222\">12 м</text></svg>","alt":"Учреждение исполнения наказаний и точка Х в 12 м от ограждения."}]}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-sch-fzt-07', 'r6-sch-fzt-uin', 'full', 2, 'fz_territorii', 'ФЗ о закрытых и охраняемых территориях, ст. 24, ч. 24.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-sch-fzt-07');
